    b (int, float, str): The second number.

Returns:
    int, float, str, or None: The larger number in its original type, or None if they are equal.
"""

# Replace comma with dot in string inputs
if isinstance(a, str):
    a = a.replace(',', '.')
if isinstance(b, str):
    b = b.replace(',', '.')

# Convert inputs to float
a_float = float(a) if isinstance(a, str) else a
b_float = float(b) if isinstance(b, str) else b

# Compare the numbers
if a_float > b_float:
    # Return the larger number in its original type
    if isinstance(a, str):
        return a.replace('.', ',')
    else:
        return a
elif a_float < b_float:
    # Return the larger number in its original type
    if isinstance(b, str):
        return b.replace('.', ',')
    else:
        return b
else:
    # Return None if the numbers are equal
    return None
